import java.util.*;import java.util.zip.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;
public class NativeChecks{
 static int n;static void ok(boolean b,String s){n++;if(!b)throw new AssertionError(s);}static ClassNode cls(ZipFile z,String path)throws Exception{var c=new ClassNode();new ClassReader(z.getInputStream(z.getEntry(path+".class")).readAllBytes()).accept(c,0);return c;}static Object val(AnnotationNode a,String key){for(int i=0;i<a.values.size();i+=2)if(a.values.get(i).equals(key))return a.values.get(i+1);return null;}
 public static void main(String[]args)throws Exception{try(var mod=new ZipFile(args[0]);var nativeJar=new ZipFile(args[1]);var old=new ZipFile(args[2])){for(String mix:List.of("compat/tacz/CursorShoot32","compat/tacz/CursorAuto32","ShoulderFire32")){var c=cls(mod,"com/cleannrooster/dungeons_iso/mixin/"+mix);var a=c.invisibleAnnotations.stream().filter(x->x.desc.endsWith("/Mixin;")).findFirst().orElseThrow();String target=(String)((List<?>)val(a,"targets")).get(0);var t=cls(nativeJar,target.replace('.','/'));for(var m:c.methods){ok(!m.name.contains("/"),"valid JVM handler name");for(var an:m.visibleAnnotations){String method=(String)((List<?>)val(an,"method")).get(0);var matched=t.methods.stream().filter(q->(q.name+q.desc).equals(method)).findFirst().orElseThrow();ok((matched.access&Opcodes.ACC_STATIC)==(m.access&Opcodes.ACC_STATIC),"native static/instance handler matches");ok(val(an,"require").equals(1),"required exact native injection");}}}
 var bridge=cls(mod,"dev/zomboid/isotacz/Bridge");var method=bridge.methods.stream().filter(m->m.name.equals("finishCamera")).findFirst().orElseThrow();int returns=0,hooks=0;for(var i:method.instructions){if(i.getOpcode()==Opcodes.RETURN)returns++;if(i instanceof MethodInsnNode q&&q.owner.equals("dev/zomboid/isotacz/ShotAim32")&&q.name.equals("before"))hooks++;}ok(hooks==returns&&hooks>0,"every camera update exit refreshes cursor direction");
 for(var en:Collections.list(old.entries()))if(en.getName().contains("Audio")||en.getName().contains("Acoustics")||en.getName().contains("SoundSystem"))ok(Arrays.equals(old.getInputStream(en).readAllBytes(),mod.getInputStream(mod.getEntry(en.getName())).readAllBytes()),"existing audio preserved "+en.getName());
 System.out.println("ACTUAL_TACZ_TPS_DESCRIPTORS_CAMERA_HOOK_AUDIO_PRESERVATION_CHECKS="+n);}}
}
